# -*- coding: utf-8 -*-
import sys, json, pathlib
sys.stdout.reconfigure(encoding='utf-8', errors='replace')

base = pathlib.Path(r'C:\Users\cherkasov.n\.cursor\projects\c-Users-cherkasov-n-openAIKey\agent-transcripts')
chat_id = sys.argv[1]
# find file
f = base / chat_id / (chat_id + '.jsonl')
if not f.exists():
    matches = list(base.rglob(chat_id + '.jsonl'))
    if matches:
        f = matches[0]

start = int(sys.argv[2]) if len(sys.argv) > 2 else 0

for i, line in enumerate(f.open(encoding='utf-8', errors='replace'), 1):
    if i < start:
        continue
    line = line.strip()
    if not line:
        continue
    try:
        o = json.loads(line)
    except Exception:
        continue
    role = o.get('role')
    content = o.get('message', {}).get('content', [])
    if not isinstance(content, list):
        continue
    texts = []
    tools = []
    for c in content:
        if not isinstance(c, dict):
            continue
        if c.get('type') == 'text' and c.get('text', '').strip():
            texts.append(c['text'])
        elif c.get('type') == 'tool_use':
            tools.append(c.get('name', '?'))
    if texts or tools:
        print(f'\n===[{i}] {role}' + (f'  (tools: {", ".join(tools)})' if tools else '') + '===')
        for t in texts:
            print(t)
